"""Builder fixtures: aiogram objects generated by the polyfactory factories.

Every `make_*` fixture is a factory: call it as often as needed, override fields by keyword.
Results that Telegram would deliver to a handler are bound to the `bot` fixture.
"""

from collections.abc import Callable
from typing import Any
from unittest.mock import AsyncMock

import pytest
from aiogram.types import CallbackQuery, Chat, ChosenInlineResult, InlineQuery, Message, User
from faker import Faker

from constants import PLACEHOLDER_PREFIX
from tests.factories import (
    CallbackQueryFactory,
    ChatFactory,
    ChosenInlineResultFactory,
    InlineQueryFactory,
    MessageFactory,
    UserFactory,
)


@pytest.fixture
def user() -> User:
    """A random human user."""
    return UserFactory.build()


@pytest.fixture
def chat() -> Chat:
    """A random private chat."""
    return ChatFactory.build()


@pytest.fixture
def inline_message_id(faker: Faker) -> str:
    """A random inline message id; the default for `make_chosen_result` and `make_callback`."""
    return str(faker.pystr())


@pytest.fixture
def make_message(bot: AsyncMock) -> Callable[..., Message]:
    """Factory `make(text=None, *, bound=True, **fields)` -> Message in a random private chat.

    Bound to the `bot` fixture unless `bound=False`; extra keyword fields override the factory.
    """

    def make(text: str | None = None, *, bound: bool = True, **fields: Any) -> Message:
        message = MessageFactory.build(text=text, **fields)
        return message.as_(bot) if bound else message

    return make


@pytest.fixture
def make_inline_query(bot: AsyncMock) -> Callable[..., InlineQuery]:
    """Factory `make(query=None, **fields)` -> InlineQuery bound to `bot`.

    Without `query` the text is random; `from_user` is a random user unless overridden.
    """

    def make(query: str | None = None, **fields: Any) -> InlineQuery:
        if query is not None:
            fields["query"] = query
        return InlineQueryFactory.build(**fields).as_(bot)

    return make


@pytest.fixture
def make_chosen_result(
    bot: AsyncMock, faker: Faker, inline_message_id: str
) -> Callable[..., ChosenInlineResult]:
    """Factory `make(result_id=None, **fields)` -> ChosenInlineResult bound to `bot`.

    `inline_message_id` defaults to the fixture of that name; `result_id` defaults to
    `PLACEHOLDER_PREFIX` plus a random key.
    """

    def make(result_id: str | None = None, **fields: Any) -> ChosenInlineResult:
        defaults: dict[str, Any] = {
            "result_id": result_id or PLACEHOLDER_PREFIX + faker.pystr(),
            "inline_message_id": inline_message_id,
        }
        return ChosenInlineResultFactory.build(**{**defaults, **fields}).as_(bot)

    return make


@pytest.fixture
def make_callback(bot: AsyncMock, inline_message_id: str) -> Callable[..., CallbackQuery]:
    """Factory `make(payload=None, **fields)` -> CallbackQuery bound to `bot`.

    `inline_message_id` defaults to the fixture of that name; `payload` becomes the button data.
    """

    def make(payload: str | None = None, **fields: Any) -> CallbackQuery:
        defaults: dict[str, Any] = {"data": payload, "inline_message_id": inline_message_id}
        return CallbackQueryFactory.build(**{**defaults, **fields}).as_(bot)

    return make
